create schema if not exists private;
create or replace function private.projectos_canonical_product_key(p_value text) returns text language sql immutable security invoker set search_path=pg_catalog as $$ select case lower(trim(coalesce(p_value,''))) when 'banatao_systems' then 'banatao_systems' when 'battle' then 'battle' when 'battle-prototype' then 'battle' when 'batalla-law-office-os' then 'battle' when 'callgate' then 'callgate' when 'callgate-platform' then 'callgate' when 'realmatch' then 'realmatch' when 'real-match' then 'realmatch' when 'fxpass' then 'fxpass' when 'fong' then 'fxpass' when 'fxpass-prototype' then 'fxpass' when 'fong-europay-prototype' then 'fxpass' when 'pandoras_box' then 'pandoras_box' when 'pandoras-box' then 'pandoras_box' when 'projectos' then 'pandoras_box' when 'project_os' then 'pandoras_box' when 'mcpmaster' then 'pandoras_box' when 'mcp_master' then 'pandoras_box' when 'mcp-master' then 'pandoras_box' when 'tessie' then 'tessie' else null end; $$;
create table if not exists private.projectos_product_registry(organization_id uuid not null,product_key text not null check(product_key in('banatao_systems','battle','callgate','realmatch','fxpass','pandoras_box','tessie')),title text not null,repo_full_name text,posthog_project_id bigint not null default 526760,posthog_dashboard_id bigint,posthog_dashboard_url text,supabase_project_ref text,status text not null default 'active' check(status in('active','paused','archived')),data_classification text not null default 'aggregate_only' check(data_classification in('aggregate_only','anonymous_technical','pseudonymous_product')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(organization_id,product_key));
create table if not exists private.projectos_event_contracts(id uuid primary key default gen_random_uuid(),organization_id uuid not null,product_key text not null,event_name text not null,purpose text not null,privacy_tier text not null default 'aggregate_only' check(privacy_tier in('aggregate_only','anonymous_technical','pseudonymous_product')),allowed_properties text[] not null default '{}',retention_days integer not null default 400 check(retention_days between 1 and 2555),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,product_key) references private.projectos_product_registry(organization_id,product_key) on delete cascade,unique(organization_id,product_key,event_name));
create table if not exists private.projectos_product_signals(id uuid primary key default gen_random_uuid(),organization_id uuid not null,product_key text not null,event_name text not null,occurred_at timestamptz not null,environment text not null default 'unknown' check(environment in('production','preview','staging','development','unknown')),source text not null default 'posthog_webhook' check(source in('posthog_webhook','posthog_batch','pandoras_box_internal','manual_import')),privacy_tier text not null default 'aggregate_only' check(privacy_tier in('aggregate_only','anonymous_technical','pseudonymous_product')),release_sha text,app_version text,deployment_id text,anonymous_actor_hash text,properties jsonb not null default '{}'::jsonb,schema_version integer not null default 1 check(schema_version between 1 and 1000),dedupe_key text not null,learnable boolean generated always as(environment='production') stored,created_at timestamptz not null default now(),foreign key(organization_id,product_key) references private.projectos_product_registry(organization_id,product_key) on delete restrict,check(jsonb_typeof(properties)='object'),check(octet_length(properties::text)<=16384),unique(organization_id,dedupe_key));
create table if not exists private.projectos_metric_snapshots(id uuid primary key default gen_random_uuid(),organization_id uuid not null,product_key text not null,metric_key text not null,window_start timestamptz not null,window_end timestamptz not null,value numeric not null,unit text not null default 'count',dimensions jsonb not null default '{}'::jsonb,source text not null default 'posthog',quality_status text not null default 'unverified' check(quality_status in('unverified','validated','suspect','rejected')),evidence_ref text,created_at timestamptz not null default now(),foreign key(organization_id,product_key) references private.projectos_product_registry(organization_id,product_key) on delete cascade,check(window_end>window_start),check(jsonb_typeof(dimensions)='object'),unique(organization_id,product_key,metric_key,window_start,window_end,source,evidence_ref));
create table if not exists private.projectos_product_observations(id uuid primary key default gen_random_uuid(),organization_id uuid not null,product_key text not null,observation_type text not null check(observation_type in('trend','anomaly','friction','conversion','retention','reliability','performance','experiment','feedback','capability_gap','cost','quality')),summary text not null check(length(summary) between 1 and 2000),confidence numeric not null default .5 check(confidence between 0 and 1),evidence jsonb not null default '[]'::jsonb,status text not null default 'active' check(status in('active','superseded','dismissed','resolved')),valid_from timestamptz not null default now(),valid_until timestamptz,created_by text not null default 'pandoras_box',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,product_key) references private.projectos_product_registry(organization_id,product_key) on delete cascade,check(jsonb_typeof(evidence)='array'),check(valid_until is null or valid_until>valid_from));
create table if not exists private.projectos_product_recommendations(id uuid primary key default gen_random_uuid(),organization_id uuid not null,product_key text not null,recommendation_key text not null,recommendation text not null check(length(recommendation) between 1 and 4000),rationale text not null check(length(rationale) between 1 and 4000),expected_metric text,baseline_value numeric,target_value numeric,confidence numeric not null default .5 check(confidence between 0 and 1),priority integer not null default 50 check(priority between 0 and 100),status text not null default 'proposed' check(status in('proposed','accepted','rejected','implemented','measuring','validated','reverted')),source_observation_ids uuid[] not null default '{}',implementation_ref text,measured_value numeric,outcome_summary text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,product_key) references private.projectos_product_registry(organization_id,product_key) on delete cascade,unique(organization_id,product_key,recommendation_key));
create table if not exists private.projectos_product_sync_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null,source text not null,status text not null default 'running' check(status in('running','succeeded','partial','failed')),started_at timestamptz not null default now(),completed_at timestamptz,cursor_value text,received_count integer not null default 0,accepted_count integer not null default 0,rejected_count integer not null default 0,duplicate_count integer not null default 0,error_code text,error_summary text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),check(completed_at is null or completed_at>=started_at),check(received_count>=0 and accepted_count>=0 and rejected_count>=0 and duplicate_count>=0),check(jsonb_typeof(metadata)='object'));
